#include <iostream>
#include <vector>
#include <string>
#include <ncurses.h>
//#include <curses.h>

using namespace std;

void drawLeft(WINDOW* ,vector<string>&  , int );
void drawChat(WINDOW* ,vector<string>&);

int main(){

    //initialize the screen
    initscr();



    keypad(stdscr,true);
    // curs_set(0);


    vector<string> sideMenu ={"General", "Sports","Programming","Music","Random"};
    vector <string> chat;

    int highlight = 0;


    //box values to allign the screen
    int terminalWidth=COLS;
    int terminalLength=LINES;

    int sidePanelWidth =20;
    int sidePanelLength = terminalLength -1;

    int y_startAt_0 = 0;
    int x_startAt_0 = 0;


    //creating new windows to hold different places on the screen
    WINDOW* mainWin = newwin((sidePanelLength -10) ,(terminalWidth-40),y_startAt_0,(x_startAt_0 + 20));
    WINDOW* mainInner = newwin((sidePanelLength -13) ,(terminalWidth-42),y_startAt_0+2,(x_startAt_0 + 21));

    WINDOW* rightWin = newwin(sidePanelLength,sidePanelWidth,y_startAt_0,(terminalWidth-20));
    WINDOW* rightInner = newwin(sidePanelLength-3,sidePanelWidth-4,y_startAt_0+2,(terminalWidth-18));

    WINDOW* leftWin = newwin(sidePanelLength,sidePanelWidth,y_startAt_0,x_startAt_0);
    WINDOW* leftInner = newwin(sidePanelLength-3,sidePanelWidth-4,y_startAt_0+2,x_startAt_0+2);

    WINDOW* bottomWin = newwin( 10 ,(terminalWidth-40),(terminalLength - 11) , (x_startAt_0 + 20) );
    WINDOW* bottomInner = newwin( 5 ,(terminalWidth-44),(terminalLength - 8) , (x_startAt_0 + 22) );


    WINDOW* bottomWins = newwin( 5 ,(terminalWidth-56),(terminalLength - 36) , (x_startAt_0 + 59) );
    box(bottomWins,0,0);
    mvwprintw(bottomWin,3,1,"newflagrchangessdfadfsafafsdfsfsdfsafd");
    wrefresh(bottomWins);
    WINDOW* bottomInners = newwin( 5 ,(terminalWidth-44),(terminalLength - 8) , (x_startAt_0 + 22) );

    drawLeft(leftInner, sideMenu, highlight);


    // box creates a border for each win and gives them a visible effect
    box(mainWin,0,0);
    box(mainInner,0,0);

    box(leftWin,0,0);
    box(leftInner,0,0);

    box(rightWin,0,0);
    box(rightInner,0,0);

    box(bottomWin,0,0);
    box(bottomInner,0,0);

    mvwprintw(mainWin,1,40,"Advanced C++ Chat Client");
    mvwprintw(leftWin,1,8,"Feed");
    mvwprintw(rightWin,1,6,"Friends");
    mvwprintw(bottomInner,1,1,"Type > ");

    wrefresh(mainWin);
    wrefresh(mainInner);
    wrefresh(rightWin);
    wrefresh(rightInner);
    wrefresh(leftWin);
    wrefresh(leftInner);
    wrefresh(bottomWin);
    wrefresh(bottomInner);


    vector<string> text;

    string type="";

    while (true){

        int typingInput = wgetch(bottomInner);

        switch(typingInput){
            case KEY_UP:{
                highlight=(highlight == 0)? sideMenu.size() -1: highlight-1;
                    drawLeft(leftInner,sideMenu,highlight);
                break;
            }
            case KEY_DOWN:{
                highlight=(highlight == sideMenu.size()-1)? 0: highlight+1;
                    drawLeft(leftInner,sideMenu,highlight);
                break;
            }
            // case KEY_LEFT:{
            //     highlight=(highlight == 0)? sideMenu.size() -1: highlight-1;
            //     break;
            // }
            // case KEY_RIGHT:{
            //     highlight=(highlight == sideMenu.size()-1)? 0: highlight+1;
            //     break;
            // }
            case KEY_ENTER :{
                if(!type.empty()){
                    text.push_back("You: "+type);
                    //chat.push_back("You: "+type);
                    drawChat(mainInner, text);

                }

                type.clear();
                wclrtoeol(bottomInner);
                wmove(bottomInner,0,2);
                mvwprintw(bottomInner,0,2,"Type > ");

                wrefresh(bottomInner);

                break;
            }
            case 127:{
                if(!type.empty()){
                    type.pop_back();
                }

                wattron(bottomInner,A_REVERSE);

                wclrtoeol(bottomInner);
                wmove(bottomInner,1,2);

                wattroff(bottomInner,A_REVERSE);

                mvwprintw(bottomInner,1,1,"Type > ", type.c_str());
                wrefresh(bottomInner);

                continue;
            }

        }
        if(typingInput >=32 || typingInput <= 126){


            type+=typingInput;

            //wclrtoeol();


        }



        // if(typingInput == KEY_BACKSPACE || typingInput == '\b' || typingInput == 127){
        //     if(!type.empty()){
        //         type.pop_back();
        //     }

        //     wattron(bottomInner,A_REVERSE);

        //     wclrtoeol(bottomInner);
        //     wmove(bottomInner,1,2);

        //     wattroff(bottomInner,A_REVERSE);

        //     mvwprintw(bottomInner,1,1,"Type > ", type.c_str());
        //     wrefresh(bottomInner);

        //     continue;
        // }
        // text.push_back("You: "+type);

        // if(typingInput == KEY_ENTER){

        //     //mvwprintw(mainWin,6,2,text);
        //     break;
        // }

        // int tacker
        // for(auto& strng;it = text.begin();it<text.end();)


    }

    endwin();

    return 0;

}

void drawLeft(WINDOW* leftInner, vector<string>& topicList , int highlight){


    int length = topicList.size();

    for(int i=0; i<length ; ++i){

        if(i == highlight){
            //start_color();
            attron(A_REVERSE);
                mvwprintw(leftInner, (i+3) ,1,"> %s",topicList[i].c_str());
            attroff(A_REVERSE);

        }else{
            mvwprintw(leftInner, (i+3) ,1,topicList[i].c_str());
        }

    }

    wrefresh(leftInner);

}

void drawChat(WINDOW* mainInner,vector<string>& text){

    int numMessages = text.size();


    for(int i=0; i< numMessages; i++){
        mvwprintw(mainInner,i,1,text[i].c_str());
    }

    wrefresh(mainInner);

}

