            wrefresh(bottomInner);


        }
    }

    endwin();

    return 0;

}

void drawLeft(WINDOW* leftInner, vector<string>& topicList , int highlight){


    int length = topicList.size();

    for(int i=0; i<length ; ++i){

        if(i == highlight){
            //start_color();
            attron(A_REVERSE);
                mvwprintw(leftInner, (i+3) ,1,"> %s",topicList[i].c_str());
            attroff(A_REVERSE);

        }else{
            mvwprintw(leftInner, (i+3) ,1,topicList[i].c_str());
        }

    }

    wrefresh(leftInner);

}

void drawChat(WINDOW* mainInner,vector<string>& text){

    werase(mainInner);


    int numMessages = text.size();

    int chatHeight,chatWidth;

    getmaxyx(mainInner,chatHeight,chatWidth);

    //the function max use a floor of zero, and ruturns where we shoudl start inside the
    //vector pending on screen size
    int displayStart= max(0, static_cast<int>(text.size()) - chatHeight);

    int rowTotal=0;
    for(int i=displayStart; i< numMessages; i++){
        mvwprintw(mainInner,rowTotal++,1,text[i].c_str());
    }

    wrefresh(mainInner);

}

